j:if.g2:evaluate:
var now = "";
now = gs.nowDateTime();
var endTime = gs.action.getGlideURI().get("end_time");
end_time = (endTime == null) ? now : endTime;
var startTime = gs.action.getGlideURI().get("start_time");
start_time = (startTime == null) ? now : startTime;
var maxRows = gs.action.getGlideURI().get("max_rows");
max_rows = (maxRows == null) ? 1000 : maxRows;
var filterSession = gs.action.getGlideURI().get("filter_session");
filter_session = (filterSession == null) ? '' : filterSession;


  var logFile =  new GlideLogFileReader();
  if (time_diff) {
	 logFile.setTimeRange(start_time, time_diff);
  } else {
	 logFile.setStartTime(start_time);
	 if (end_time) {
		logFile.setEndTime(end_time);
		}
  }

  if (max_rows)
	 logFile.setMaxRows(max_rows);

  var session_message = "";
  if (typeof filter_session == 'undefined' || filter_session == '') 
	 filter_session = 'null';

  if (typeof match_session == 'undefined') 
	 match_session = '';

  logFile.setSession(filter_session);
  logFile.setMatchSession(match_session);
  logFile.setLevel(level);
  logFile.setMessage(message);
  logFile.setThread(filter_thread);
  logFile.setOmitWorkers(omit_workers);
  var system_start_time = logFile.getStartTime();
  var system_end_time = logFile.getEndTime();
  logFile.open();

