var tstamp = logFile.getValue('timestamp');
if (tstamp) {
   var parts = tstamp.split(' ');
   tstamp = parts[1];
}
tstamp;

var level = logFile.getValue('level');
if (level == '0')
	level = gs.getMessage('Info');
else if (level == '1')
	level = gs.getMessage('Warning');
else if (level == '2')
	level = gs.getMessage('Error');
else if (level == '3')
	level = gs.getMessage('Debug');
else if (level == '5')
	level = gs.getMessage('Trace');
else if (level == '6')
	level = gs.getMessage('Fatal');
level;


